def merge(intervals):
    intervals.sort(key=lambda x: x[0])
    result = []
    for start, end in intervals:
        if result and start <= result[-1][1]:
            result[-1][1] = max(result[-1][1], end)   # overlaps, extend the last
        else:
            result.append([start, end])                # no overlap, add a new one
    return result

print(merge([[1, 3], [2, 6], [8, 10]]))   # [[1, 6], [8, 10]]

def can_attend_all(intervals):
    intervals.sort(key=lambda x: x[0])
    for i in range(1, len(intervals)):
        if intervals[i][0] < intervals[i - 1][1]:
            return False       # this meeting starts before the last ends
    return True

def intersect(a, b):
    i = j = 0
    result = []
    while i < len(a) and j < len(b):
        lo = max(a[i][0], b[j][0])
        hi = min(a[i][1], b[j][1])
        if lo <= hi:
            result.append([lo, hi])     # they overlap here
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return result
